    double eps = maxc;
    if (eps <= 0.0) eps = 1.0;
    int* unassigned = (int*)malloc(n * sizeof(int));
    int* obj_to_person = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) { assign[i] = -1; obj_to_person[i] = -1; }
    while (eps > eps_final) {
        eps /= theta;
