Here's a clean JV implementation (I'll write it carefully):

```c
void lapjv(int n, const double* cost, int* x, int* y) {
    // x[i] = column assigned to row i, y[j] = row assigned to column j
    int i, j, j1, i0, numfree, l;
    int* freev = malloc(n * sizeof(int));
    int* pred = malloc(n * sizeof(int));
    double* u = malloc(n * sizeof(double));
    double* v = malloc(n * sizeof(double));
    double* d = malloc(n * sizeof(double));
    char* ready = malloc(n * sizeof(char));
    double BIG = 1e300;

    // column reduction
    for (j = 0; j < n; j++) {
        v[j] = cost[j];
        for (i = 1; i < n; i++)
            if (cost[i*n+j] < v[j]) v[j] = cost[i*n+j];
        y[j] = -1;
    }

    // reduction transfer
    for (i = 0; i < n; i++) {
        double c0 = cost[i*n] - v[0];
        j1 = 0;
        double c1 = BIG;
        for (j = 1; j < n; j++) {
            double c = cost[i*n+j] - v[j];
            if (c < c0) { c1 = c0; c0 = c; j1 = j; }
            else if (c < c1) c1 = c;
        }
        u[i] = c0;
        if (y[j1] == -1) { y[j1] = i; x[i] = j1; }
        else x[i] = -1;
    }

    // augmenting row reduction
    numfree = 0;
    for (i = 0; i < n; i++)
        if (x[i] == -1) freev[numfree++] = i;
    for (l = 0; l < numfree; l++) {
        i = freev[l];
        double c0 = cost[i*n] - u[i] - v[0];
        j1 = 0;
        double c1 = BIG;
        for (j = 1; j < n; j++) {
            double c = cost[i*n+j] - u[i] - v[j];
            if (c < c0) { c1 = c0; c0 = c; j1 = j; }
            else if (c < c1) c1 = c;
        }
        v[j1] -= c1 - c0;
        i0 = y[j1];
        y[j1] = i;
        x[i] = j1;
        if (i0 != -1) { x[i0] = -1; freev[numfree++] = i0; }
    }

    // augmenting phase
    for (l = 0; l < numfree; l++) {
        i0 = freev[l];
        for (j = 0; j < n; j++) {
            d[j] = cost[i0*n+j] - u[i0] - v[j];
            pred[j] = i0;
            ready[j] = 0;
        }
        while (1) {
            double dmin = BIG;
            j1 = -1;
            for (j = 0; j < n; j++)
                if (!ready[j] && d[j] < dmin) { dmin = d[j]; j1 = j; }
            ready[j1] = 1;
            i = y[j1];
            if (i == -1) break;
            for (j = 0; j < n; j++)
                if (!ready[j]) {
                    double nd = dmin + cost[i*n+j] - u[i] - v[j];
                    if (nd < d[j]) { d[j] = nd; pred[j] = i; }
                }
        }
        double dstar = d[j1];
        for (j = 0; j < n; j++)
            if (ready[j]) v[j] += d[j] - dstar;
        u[i0] += dstar;
        for (i = 0; i < n; i++)
            if (i != i0 && x[i] != -1 && ready[x[i]]) u[i] += dstar - d[x[i]];
        j = j1;
        while (j != -1) {
            i = pred[j];
            int j_prev = x[i];
            y[j] = i;
            x[i] = j;
            j = j_prev;
        }
    }

    free(freev); free(pred); free(u); free(v); free(d); free(ready);
}
```

