#include <stdlib.h>
#include <immintrin.h>

static inline void scan_row(const double* ci, const double* price, int n, int* best_j, double* second) {
    __m256d best = _mm256_set1_pd(1e300);
    __m256d secondv = _mm256_set1_pd(1e300);
    __m256i best_idx = _mm256_set1_epi64x(-1);
    __m256i idx = _mm256_setr_epi64x(0, 1, 2, 3);
    __m256i stride = _mm256_set1_epi64x(4);
    int j = 0;
    for (; j + 4 <= n; j += 4) {
        __m256d v = _mm256_add_pd(_mm256_loadu_pd(ci + j), _mm256_loadu_pd(price + j));
        __m256d m1 = _mm256_cmp_pd(v, best, _CMP_LT_OQ);
        secondv = _mm256_blendv_pd(secondv, best, m1);
        best = _mm256_min_pd(best, v);
        best_idx = _mm256_blendv_epi8(best_idx, idx, _mm256_castpd_si256(m1));
        __m256d m2 = _mm256_andnot_pd(m1, _mm256_cmp_pd(v, secondv, _CMP_LT_OQ));
        secondv = _mm256_blendv_pd(secondv, v, m2);
        idx = _mm256_add_epi64(idx, stride);
    }
    double b[4], s[4];
    long long bi[4];
    _mm256_storeu_pd(b, best);
    _mm256_storeu_pd(s, secondv);
    _mm256_storeu_si256((__m256i*)bi, best_idx);
    double gb = b[0]; int gbi = (int)bi[0];
    for (int k = 1; k < 4; k++) { if (b[k] < gb) { gb = b[k]; gbi = (int)bi[k]; } }
    double gs = 1e300;
    for (int k = 0; k < 4; k++) {
        double cand = (b[k] == gb) ? s[k] : b[k];
        if (cand < gs) gs = cand;
    }
    for (; j < n; j++) {
        double v = ci[j] + price[j];
        if (v < gb) { gs = gb; gb = v; gbi = j; }
        else if (v < gs) gs = v;
    }
    *best_j = gbi;
    *second = gs;
}

void auction(int n, const double* cost, int* assign_person, double* price, double eps_final, double theta, long long* nbids) {
    int* assign_obj = (int*)malloc(n * sizeof(int));
    // init price to -column min
    for (int j = 0; j < n; j++) {
        double mn = cost[j];
        for (int i = 1; i < n; i++) if (cost[i*n+j] < mn) mn = cost[i*n+j];
        price[j] = -mn;
        assign_person[j] = -1;
        assign_obj[j] = -1;
    }
    double maxc = 0.0;
    for (int i = 0; i < n*n; i++) if (cost[i] > maxc) maxc = cost[i];
    double eps = maxc;
    if (eps <= 0.0) eps = 1.0;
    int* unassigned = (int*)malloc(n * sizeof(int));
    long long bids = 0;
    while (eps > eps_final) {
        eps /= theta;
        for (int i = 0; i < n; i++) {
            if (assign_person[i] != -1) {
                int j_i = assign_person[i];
                const double* ci = cost + (size_t)i*n;
                int best_j; double second;
                scan_row(ci, price, n, &best_j, &second);
                double best = ci[best_j] + price[best_j];
                if (ci[j_i] + price[j_i] > best + eps) {
                    assign_obj[j_i] = -1;
                    assign_person[i] = -1;
                }
            }
        }
        int cnt = 0;
        for (int i = 0; i < n; i++) if (assign_person[i] == -1) unassigned[cnt++] = i;
        while (cnt > 0) {
            cnt--;
            int i = unassigned[cnt];
            const double* ci = cost + (size_t)i*n;
            int best_j; double second;
            scan_row(ci, price, n, &best_j, &second);
            double best = ci[best_j] + price[best_j];
            double bid = second - best + eps;
            price[best_j] += bid;
            bids++;
            int prev = assign_obj[best_j];
            assign_obj[best_j] = i;
            assign_person[i] = best_j;
            if (prev != -1) { assign_person[prev] = -1; unassigned[cnt++] = prev; }
        }
    }
    *nbids = bids;
    free(assign_obj); free(unassigned);
}
