        for (int j = 0; j < n; j++) { assign[j] = -1; price[j] = 0.0; }
        int cnt = n;
        for (int i = 0; i < n; i++) unassigned[i] = i;
        while (cnt > 0) {
            // parallel: each unassigned person computes best & second, bid
            #pragma omp parallel for schedule(static)
            for (int k = 0; k < cnt; k++) {
                int i = unassigned[k];
                const double* ci = cost + (size_t)i*n;
                double best = 1e300, second = 1e300;
                int best_j = -1;
                for (int j = 0; j < n; j++) {
                    double v = ci[j] + price[j];
                    if (v < best) { second = best; best = v; best_j = j; }
                    else if (v < second) second = v;
                }
                bid_val[k] = second - best + eps;
                bid_obj[k] = best_j;
            }
            // resolve conflicts via counting sort
            for (int j = 0; j <= n; j++) count[j] = 0;
            for (int k = 0; k < cnt; k++) count[bid_obj[k]+1]++;
            for (int j = 0; j < n; j++) count[j+1] += count[j];
            for (int k = 0; k < cnt; k++) sorted[count[bid_obj[k]]++] = k;
            // for each object, find max bid
            #pragma omp parallel for schedule(static)
            for (int j = 0; j < n; j++) {
                double mb = -1e300; int mb_i = -1;
                for (int t = count[j]; t < count[j+1]; t++) {
                    int k = sorted[t];
                    if (bid_val[k] > mb) { mb = bid_val[k]; mb_i = unassigned[k]; }
                }
                obj_bid[j] = mb; obj_bidder[j] = mb_i;
