            // update prices and assignments
            int new_cnt = 0;
            for (int j = 0; j < n; j++) {
                if (obj_bidder[j] != -1) {
                    price[j] += obj_bid[j];
                    int prev = assign[j];
                    assign[j] = obj_bidder[j];
                    if (prev != -1) unassigned[new_cnt++] = prev;
                }
            }
            cnt = new_cnt;
        }
    }
    free(unassigned); free(bid_val); free(bid_obj); free(obj_bid); free(obj_bidder); free(count); free(sorted);
}
